query:
query SearchProducts($filters: SearchProductsFiltersInput!) {
  site {
    search {
      searchProducts(filters: $filters) {
        products(first: 10) {
          collectionInfo {
            totalItems
          }
          pageInfo {
            hasNextPage
            endCursor
          }
          edges {
            node {
              entityId
              name
              path
              brand {
                entityId
                name
              }
              defaultImage {
                url(width: 320)
                altText
              }
              prices {
                price {
                  value
                  currencyCode
                }
                basePrice {
                  value
                  currencyCode
                }
                salePrice {
                  value
                  currencyCode
                }
              }
            }
          }
        }
        filters(first: 25) {
          pageInfo {
            hasNextPage
            endCursor
          }
          edges {
            node {
              __typename
              displayName
              isCollapsedByDefault
              ... on BrandSearchFilter {
                displayProductCount
                brands(first: 50) {
                  edges {
                    node {
                      entityId
                      name
                      isSelected
                      productCount
                    }
                  }
                }
              }
              ... on CategorySearchFilter {
                displayProductCount
                categories(first: 50) {
                  edges {
                    node {
                      entityId
                      name
                      isSelected
                      productCount
                    }
                  }
                }
              }
              ... on ProductAttributeSearchFilter {
                filterKey
                displayProductCount
                attributes(first: 50) {
                  edges {
                    node {
                      value
                      isSelected
                      productCount
                    }
                  }
                }
              }
              ... on RatingSearchFilter {
                ratings(first: 10) {
                  edges {
                    node {
                      value
                      isSelected
                      productCount
                    }
                  }
                }
              }
              ... on PriceSearchFilter {
                selected {
                  minPrice
                  maxPrice
                }
              }
            }
          }
        }
        suggestions {
          sourceField
          results {
            text
          }
        }
      }
    }
  }
}
